    beats = {
        { id = "blackbird", at = 15, title = "The blackbird",
            text = "I began as a seed in a black berry, and a blackbird swallowed the berry whole one March. I was dropped, rather rudely, at the foot of an old house. I have forgiven the blackbird. I have also told everyone about the blackbird." },
        { id = "the_dark", at = 40, title = "Toward the shade",
            text = "Young ivy grows toward the shade, feeling for something tall to hold. I crept along the ground for two summers. Then one morning there was brick under my rootlets, warm and rough and old. I held on. I have been holding on ever since." },
        { id = "window", at = 80, title = "The library window",
            text = "Halfway up that wall was a window, and behind the window a library, shelves to the ceiling. A girl read there every afternoon with her feet tucked under her. I climbed faster that year than any year since. I wanted to see the pages." },
        { id = "house", at = 140, title = "The house talks",
            text = "Old houses talk, if you live on them long enough. I learned the cook's moods, the cat's routes, who argued about money on the stairs. I learned the girl liked stories with storms in. I told nobody. I was young and very discreet. That did not last." },
        { id = "flowers", at = 220, title = "Last flowers",
            text = "My first autumn up high, my leaves changed shape and I flowered. The girl, grown now, leaned out and said mine were the last flowers of the year. I was not offended. I was thrilled. Last means everybody comes to you." },
        { id = "brick", at = 320, title = "The loose brick",
            text = "Beside the library window there was a loose brick. One night I watched her slide the brick out, put something behind, and slide the brick back. Then she looked straight at me. I have never said a word about what I saw. Not even to you. Not yet." },
        { id = "empty", at = 450, title = "The empty rooms",
            text = "Then the house went quiet. The shelves were boxed, the curtains came down, and nobody read at the window any more. I held that wall through three winters with no lamp behind the glass. Green the whole time. Somebody had to keep the place looking loved." },
        { id = "berries", at = 600, title = "The lean months",
            text = "In the empty years the blackbirds came for my berries at the end of every winter, when nothing else was left. I fed them all, and told them about the girl and the library. Terrible listeners. They came back every year anyway." },
        { id = "cutting", at = 800, title = "The pocket",
            text = "One spring a gardener came to mend the old wall and cut me back hard. Kindly, though. She took a stem of me home in her pocket and set the stem in a pot by her door. That stem is me. The rest of me is still on the old wall, holding on." },
        { id = "your_wall", at = 1050, title = "Your wall",
            text = "From her door I came, by way of pots and hands, to your wall. The first evening a light came on in your window, and someone sat down with a book, feet tucked under. I nearly let go of the brick." },
        { id = "holding", at = 1400, title = "Holding on",
            text = "{total} pages I have listened to through your window. I hold on to everything, love: walls, stories, the sound of a page. People call clinging a weakness. I think clinging is only a way of saying stay." },
        { id = "behind", at = 1800, title = "Behind the brick",
            text = "All right. Behind the loose brick there was a small worn book, with one of my leaves pressed in for a marker. She kept me in her book. I never knew why. I think now she wanted somebody to hold her place. I am holding yours, love. I always will." },
    },
